// Clears rendered files from output/ that can be made again, and never touches anything that can't.
//
//   node scripts/clean-output.ts                 clean everything that is safe to clean
//   node scripts/clean-output.ts --slug <slug>   only that slug
//   node scripts/clean-output.ts --dry-run       list what would go, delete nothing
//
// DELETED (all of these can be regenerated by re-rendering the brief):
//   output/_build/**                    render scratch
//   output/_masters/**/*.png            2x lossless masters (git-ignored, never published)
//   untracked renders                   .jpg/.jpeg/.png/.mp4 and manifest-*.json not committed to git yet
//
// KEPT, always:
//   anything committed to git           delivery files + manifests of content in a PR or on main. The PR check,
//                                       the on-merge scheduling and manual re-runs all read them
//   caption.txt                         written copy, not a render, so it can't be regenerated
//   publish-log.jsonl                   local record of what was sent to Buffer
//   any other file                      unknown, so it's left alone and listed
//
// To remove a committed slug for real, use `git rm -r` on purpose. There is deliberately no flag for it here.
import { readdirSync, rmSync, rmdirSync, statSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { ROOT } from './lib/brand.ts';
import { OUTPUT, assertSlug } from './lib/output.ts';

const USAGE = `Usage: npm run clean:output -- [--slug <slug>] [--dry-run]

  (no flags)       clean every slug
  --slug <slug>    clean only this slug
  --dry-run        list what would be deleted, delete nothing
  --help           show this help

Deletes:    output/_build/**, 2x master PNGs, renders not committed to git yet
Never:      committed files, caption.txt, publish-log.jsonl, unknown files`;
const args = process.argv.slice(2);
if (args.includes('--help') || args.includes('-h')) { console.log(USAGE); process.exit(0); }
const dryRun = args.includes('--dry-run');
const slugIdx = args.indexOf('--slug');
const slugArg = slugIdx >= 0 ? args[slugIdx + 1] : undefined;
const unknown = args.filter((a, i) => a !== '--dry-run' && a !== '--slug' && !(slugIdx >= 0 && i === slugIdx + 1));
if (unknown.length || (slugIdx >= 0 && (!slugArg || slugArg.startsWith('--')))) {
  console.error(`Unknown or incomplete arguments: ${unknown.join(' ') || '--slug needs a value'}\n${USAGE}`);
  process.exit(1);
}
const slug = slugArg === undefined ? undefined : assertSlug(slugArg);

if (!existsSync(OUTPUT)) { console.log('output/ does not exist. Nothing to clean.'); process.exit(0); }

const rel = (p: string) => path.relative(ROOT, p).split(path.sep).join('/');

// Files git tracks under output/. If git can't answer, stop: guessing could delete committed content.
let tracked: Set<string>;
try {
  const out = execFileSync('git', ['ls-files', '-z', '--', 'output'], { cwd: ROOT, encoding: 'utf8' });
  tracked = new Set(out.split('\0').filter(Boolean));
} catch {
  console.error('Could not read the list of committed files from git. Nothing was deleted.');
  process.exit(1);
}

const NEVER_DELETE = new Set(['caption.txt', 'publish-log.jsonl']);
const RENDER_EXT = new Set(['.jpg', '.jpeg', '.png', '.mp4']);

type Verdict = 'delete' | 'keep-committed' | 'keep-protected' | 'keep-unknown';
function judge(file: string): Verdict {
  const r = rel(file);              // output/<area>/<slug>/<...>
  const [, area] = r.split('/');
  const name = path.basename(r);
  if (NEVER_DELETE.has(name)) return 'keep-protected';
  if (tracked.has(r)) return 'keep-committed';
  if (area === '_build') return 'delete';
  if (RENDER_EXT.has(path.extname(name).toLowerCase())) return 'delete';
  if (/^manifest-[a-z]+\.json$/.test(name)) return 'delete';
  return 'keep-unknown';
}

function inScope(file: string): boolean {
  if (!slug) return true;
  const parts = rel(file).split('/');
  return parts.length >= 4 && parts[2] === slug;
}

function walk(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap(e => {
    const p = path.join(dir, e.name);
    return e.isDirectory() ? walk(p) : [p];
  });
}

const files = walk(OUTPUT).filter(inScope);
const by: Record<Verdict, string[]> = { 'delete': [], 'keep-committed': [], 'keep-protected': [], 'keep-unknown': [] };
for (const f of files) by[judge(f)].push(f);

let bytes = 0;
for (const f of by.delete) {
  bytes += statSync(f).size;
  if (dryRun) console.log(`would delete  ${rel(f)}`);
  else rmSync(f, { force: true });
}

// Remove folders left empty (never output/ itself).
function pruneEmpty(dir: string): void {
  for (const e of readdirSync(dir, { withFileTypes: true })) if (e.isDirectory()) pruneEmpty(path.join(dir, e.name));
  if (dir !== OUTPUT && readdirSync(dir).length === 0) rmdirSync(dir);
}
if (!dryRun) pruneEmpty(OUTPUT);

const mb = (bytes / 1024 / 1024).toFixed(1);
console.log(`\n${dryRun ? 'Would delete' : 'Deleted'} ${by.delete.length} file(s), ${mb} MB${slug ? ` for ${slug}` : ''}.`);
console.log(`Kept ${by['keep-committed'].length} committed file(s) and ${by['keep-protected'].length} caption/publish-log file(s).`);
for (const f of by['keep-unknown']) console.log(`Kept unknown file (not a render): ${rel(f)}`);
